import { mkdir, cp, access, rename, writeFile, rm } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = fileURLToPath(new URL("../", import.meta.url));
await mkdir(path.join(root, "public/vision"), { recursive: true });
for (const file of [
  "vision_wasm_module_internal.js",
  "vision_wasm_module_internal.wasm",
]) {
  await cp(
    path.join(root, "node_modules/@mediapipe/tasks-vision/wasm", file),
    path.join(root, "public/vision", file),
  );
}
// Clear unused variants generated by earlier asset preparation.
for (const file of [
  "vision_wasm_internal.js",
  "vision_wasm_internal.wasm",
  "vision_wasm_nosimd_internal.js",
  "vision_wasm_nosimd_internal.wasm",
]) {
  await rm(path.join(root, "public/vision", file), { force: true });
}
const model = path.join(root, "public/models/hand_landmarker.task");
try {
  await access(model);
} catch {
  console.log(
    "Downloading the official MediaPipe hand model (first run only)…",
  );
  await mkdir(path.dirname(model), { recursive: true });
  const response = await fetch(
    "https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task",
    { signal: AbortSignal.timeout(120000) },
  );
  if (!response.ok)
    throw new Error(`Model download failed: ${response.status}`);
  const bytes = new Uint8Array(await response.arrayBuffer());
  if (bytes.byteLength < 1000000)
    throw new Error("Hand model download is incomplete.");
  const temporary = `${model}.tmp`;
  try {
    await writeFile(temporary, bytes);
    await rename(temporary, model);
  } finally {
    await rm(temporary, { force: true });
  }
}
console.log("Local hand-tracking assets ready.");
